/** Computes the normalized transition surprise cost (0.0 .. 1.0) between chords a and b. */
inline float corpusTransitionCost (Chord a, Chord b, int tonic, int scaleIdx, CorpusStyle style) noexcept
{
    if (style == CorpusStyle::Free)
        return 0.5f; // Neutral unweighted prior

    const int cluster = std::clamp ((int) style, 0, kNumCorpusClusters - 1);
    const int tA = corpusTokenOf (a, tonic);
    const int tB = corpusTokenOf (b, tonic);
    const uint8_t raw = kCorpusMatrices[cluster][tA][tB];
    float cost = (float) raw / 255.0f;

    // Diatonic mode bonus: reward chords that are diatonic in the active scale (e.g. bVII in Mixolydian, IV in Dorian)
    const int outB = tonesOutsideScale (b, tonic, scaleIdx);
    if (outB == 0)
        cost *= 0.85f;
    else if (outB >= 2)
        cost = std::min (1.0f, cost + 0.15f);

    return cost;
}

